  _ = `Bundle collectif`,
  v = `Facultatif\xA0:\xA0vous pouvez inviter d'autres équipes de développement pour inclure leurs jeux dans votre bundle. Comme vous avez créé ce bundle, c'est à vous qu'il revient de coordonner les équipes de développement et de publier le bundle sur le magasin Steam. Les équipes de développement invitées pourront choisir les jeux et les packages à inclure. Quand un package est ajouté au bundle ou qu'un pourcentage de réduction est modifié, les personnes qui ont ajouté un jeu doivent valider ce changement pour leur titre avant publication du bundle.`,
  y = `Invitation par code de contact`,
