  C = `Voulez-vous annuler les changements non sauvegardés\xA0?`,
  w = `Tableau de bord des pages promotionnelles`,
  T = `Pages d'évènements promotionnels`,
  E = `Les pages promotionnelles sur Steam qui mettent en avant un ou plusieurs des jeux dont vous avez les droits de gestion seront affichées ici. Ces pages sont gérées par les personnes qui organisent l'évènement ou par Valve dans le cas de promotions organisées.`,
  D = `Voici les pages promotionnelles actives et en préparation créées par Valve ou un groupe externe approuvé. Pour permettre à une ou un nouveau partenaire de créer sa propre page promotionnelle, %1$s. Vous pouvez aussi lui envoyer %2$s.`,
