  M = `Pages à la une des soldes saisonniers à venir\xA0: %1$s`,
  N = `Il est prévu que ces pages promotionnelles soient mises en avant sur la page d'accueil de Steam lors des prochains soldes saisonniers majeurs (en supposant que les jeux inclus seront en promotion). Assurez-vous que tous les titres pertinents de votre franchise y figurent.`,
