  fb = `Cette option permet d'afficher les images de capsule des applications incluses dans le package dans la zone d'achat du package dans le magasin, de la même manière que pour les contenus d'un bundle. L'image de capsule de l'application de base sera affichée en premier, suivie des autres applications incluses, triées par prix décroissant.`,
  pb = `Masquer le nom du jeu au début de la liste des articles inclus dans le package.`,
  mb = `Cette option permet de rendre la section moins verbeuse et d'améliorer sa lisibilité en enlevant le nom du jeu ainsi que les espaces vides et les signes de liaison (deux-points, traits d'union) au début des noms d'articles dépendants (DLC, bandes-son) lorsqu'ils apparaissent dans la zone d'achat du package. Par exemple, «\xA0Half-Life\xA02: Episode One\xA0» sera réduit à «\xA0Episode One\xA0». Seuls le nom exact du jeu de base, les espaces vides ainsi que les séparateurs courants tels que les tirets et les deux-points seront masqués.`,
