  cC = `Vous devez appliquer une remise de moins de %1$s\xA0% sur ce package, car le prix réduit ne peut pas être en dessous de 0,49\xA0USD, quels que soient la monnaie ou le pays.`,
  lC = `Le prix de base de ce package est inférieur au minimum autorisé dans une ou plusieurs devises. Vous ne pouvez donc pas lui attribuer de remise.`,
  uC = `Les packages avec ce symbole sont ajoutés à une remise qui est déjà en cours. Une fois enregistrées, les remises que vous avez saisies entreront en vigueur immédiatement.`,
  dC = `Cette remise programmée va faire descendre le prix du package en dessous du prix plancher dans une ou plusieurs devises. En l'état, ce package ne pourra pas être acheté dans les pays concernés. Pour garantir que ce package puisse être acheté partout, veuillez saisir un pourcentage de remise inférieur à %1$s\xA0%.`,
  fC = `Le prix de base de ce package dans une ou plusieurs devises est inférieur au minimum autorisé. Ce package ne pourra donc pas être acheté dans les pays où cette réduction fera descendre le prix final en dessous du seuil requis. Pour garantir que ce package puisse être acheté partout, veuillez en actualiser le prix pour qu'il atteigne au moins le prix plancher sur Steam.`,
  pC = `Vous avez une\xA0modification non enregistrée. Si vous l'ignorez, les nouvelles réductions ne seront pas prises en compte et les réductions modifiées reviendront à leur état antérieur.`,
