  QT = `PUBLICATION IMPOSSIBLE POUR LE MOMENT`,
  $T = `<1>Une erreur s'est produite lors de la préparation de la publication de ce changement de prix.</1><2>Veuillez réessayer. Si le problème persiste, contactez Valve.</2>`,
  eE = `<1>Une erreur s'est produite lors de la publication de ce changement de prix.</1><2>Veuillez réessayer. Si le problème persiste, contactez Valve.</2>`,
  tE = `vue compacte`,
  nE = `Sélectionnez un prix ci-dessous pour le fixer en dollars américains et appliquer les conversions recommandées dans toutes les autres devises.`,
  rE = `Afficher les packages dont le prix est inférieur au minimum autorisé (%1$s)`,
  iE = `Afficher tous les packages`,
  aE = `Afficher les packages avec une modification de prix proposée`,
  oE = `Afficher les packages modifiés localement`,
  sE = `Vous ne pouvez pas augmenter le prix d'un abonnement. Veuillez contacter Steam si vous avez besoin de le faire.`,
  cE = `Le prix doit être d'au moins %1$s. S'il reste en dessous de ce seuil, ce package ne sera pas disponible à l'achat pour la clientèle des pays utilisant cette devise.`,
  lE = `Votre prix actuel est inférieur à ce qui est habituellement autorisé pour cette devise. Vous pouvez le conserver, mais cela limitera les remises que vous pourrez appliquer à votre jeu, afin de garantir que le prix réduit reste supérieur au montant minimal de transaction autorisé.`,
  uE = `%1$s\xA0: le prix en %2$s de %3$s est inférieur au minimum en %2$s de %4$s. Veuillez vérifier s'il y a une faute de frappe (par exemple un chiffre manquant), puis saisir %4$s ou plus.`,
  dE = `%1$s\xA0: le prix en %2$s de %3$s est supérieur au prix actuel de %4$s. Le prix d'un abonnement ne peut pas être augmenté, veuillez donc saisir %4$s ou moins. Merci de prendre contact avec Steam si vous avez besoin d'augmenter le prix.`,
  fE = `1\xA0autre changement de prix ci-dessous est également en dehors de la plage autorisée.`,
  pE = `%1$s\xA0autres changements de prix ci-dessous sont également en dehors de la plage autorisée.`,
  mE = `Ces prix doivent être corrigés pour être proposés. Consultez la <1>page de la documentation sur la tarification</1> pour en savoir plus.`,
  hE = `Basé sur votre méthode de conversion sélectionnée et le prix en USD, le prix renseigné est nettement supérieur au prix conseillé (%1$s).`,
  gE = `Basé sur votre méthode de conversion sélectionnée et le prix en USD, le prix renseigné est nettement inférieur au prix conseillé (%1$s).`,
  _E = `Sur la base de votre méthode de conversion sélectionnée et du prix renseigné en USD, le prix que vous avez indiqué est nettement inférieur au prix conseillé (%1$s). Cela aura des conséquences sur vos remises, qui ne pourront pas aller au-delà de –%1$s\xA0%, car un prix réduit ne peut pas être inférieur à 0,49\xA0USD.`,
  vE = `Le prix saisi est %1$s plus élevé que le prix actuellement enregistré.`,
  yE = `Le prix saisi est %1$s plus bas que le prix actuellement enregistré.`,
  bE = `Vos remises ne pourront donc pas aller au-delà de –%1$s\xA0%, car le prix réduit ne peut pas être inférieur à 0,49\xA0USD.`,
  xE = `Vos réductions ne pourront donc pas aller au-delà de –%1$s\xA0%, car le prix réduit ne peut pas être inférieur à 0,49\xA0USD.`,
