  LR = `Date de sortie prévue\xA0`,
  RR = `Il s'agit de la date à laquelle vous comptez publier ce contenu pour le public. Cette date permet de définir des rappels sur le tableau de bord\xA0Steamworks de votre équipe. Veuillez utiliser votre fuseau horaire local.`,
  zR = `Date de publication`,
  BR = `La date à laquelle la clientèle a pu accéder à ce contenu pour la première fois`,
