  tz = `Si vous ne connaissez pas encore la date de sortie exacte de ce contenu, vous pouvez afficher une date plus approximative pour le public.`,
  nz = `Titre du lancement de contenu (public)`,
  rz = `Comment se nomme ce contenu\xA0?`,
  iz = `Description du lancement de contenu (publique)`,
  az = `Ce sous-titre, long ou court selon vos préférences, permet de décrire au public les contenus inclus dans cette sortie. Si vous avez l'intention de publier ce contenu sous forme de DLC, cette description peut être identique à celle de la page du magasin consacrée à votre DLC.`,
  oz = `Largeur d'affichage maximale des images\xA0: 584\xA0pixels`,
  sz = `Sélectionnez un DLC disponible «\xA0Prochainement\xA0» (facultatif)`,
  cz = `Effacer le DLC sélectionné`,
  lz = `Si cette option est sélectionnée, la description et la capsule du DLC disponible «\xA0Prochainement\xA0» dans le magasin apparaitront dans les descriptions ci-dessus.`,
  uz = `Prochainement`,
  dz = `Indiquer comme publié`,
  fz = `Modifier les paramètres de sortie`,
  pz = `Marquer %1$s comme publié`,
  mz = `Ce contenu est-il disponible pour la clientèle\xA0?`,
  hz = `Ce contenu est signalé comme déjà publié. Souhaitez-vous indiquer au public que ce contenu est déjà disponible\xA0? (Facultatif)`,
  gz = `Comment ce contenu est-il distribué\xA0?`,
  _z = `En tant que mise à jour du jeu\xA0: du nouveau contenu est inclus dans le jeu de base ou utilise un DLC masqué.`,
  vz = `Assurez-vous de publier votre build mis à jour, ainsi qu'une annonce\xA0Steam avec des détails sur le contenu.`,
  yz = `En tant que DLC\xA0: le nouveau contenu est représenté par une nouvelle page de DLC dans le magasin\xA0Steam.`,
