  pV = `Vous n'avez pas l'autorisation de consulter l'historique d'associations de cette application.`,
  mV = `Aucun nom d'équipe de développement, d'éditeur ou de franchise n'a encore été associé à une page d'accueil de conception pour cette application.`,
