  OV = `Il semble que vous deviez toujours répondre à votre <1>enquête sur le contenu</1>, ce qui pourrait résoudre les restrictions liées à des classifications manquantes.`,
  kV = `Enregistrement de parties\xA0: gestion des icônes de timeline`,
  AV = `Les icônes créées ici peuvent être utilisées pour signaler des moments spécifiques au sein de la timeline de votre enregistrement de partie. Steam propose aussi un ensemble d'icônes par défaut que vous êtes libre d'utiliser. Consultez la documentation pour en savoir plus.`,
