  RV = `Utilisé par les appels d'API (max. %1$s\xA0caractères)`,
  zV = `L'identifiant unique des icônes publiques ne peut pas être modifié.`,
  BV = `Couleur`,
  VV = `saisir l'identifiant unique…`,
  HV = `Utilisé par les appels d'API , doit faire entre 3 et %1$s\xA0caractères alphanumériques en minuscules. Les symboles «\xA0_\xA0» et «\xA0-\xA0» sont acceptés, mais pas les espaces.`,
  UV = `L'identifiant contient des caractères non pris en charge. Il doit faire entre 3 et %1$s\xA0caractères alphanumériques et être en minuscules. Les symboles «\xA0_\xA0» et «\xA0-\xA0» sont acceptés, mais pas les espaces.`,
  WV = `L'identifiant ne peut pas commencer avec le mot «\xA0steam_\xA0», qui est déjà utilisé pour les icônes officielles.`,
  GV = `Pour chaque icône, mettez en ligne un fichier PNG ou SVG et donnez-lui un identifiant unique utilisable par les appels d'API.`,
  KV = `Icône (fichiers SVG ou PNG)`,
  qV = `Les icônes\xA0SVG s'afficheront dans une zone de 36\xA0px\xA0×\xA036\xA0px. Veuillez créer les ressources en conséquence. Les PNG doivent être des ressources carrées faisant entre 24 et 256\xA0px de côté.`,
  JV = `Les icônes\xA0SVG s'afficheront dans une zone de 36\xA0px\xA0×\xA036\xA0px. Veuillez créer les ressources en conséquence. Les PNG doivent être des ressources carrées faisant entre 24 et 256\xA0px de côté.`,
  YV = `Ce fichier SVG a un attribut viewBox ou une largeur/hauteur de %1$s. Il se peut qu'il ne s'affiche pas correctement.`,
  XV = `Parcourir…`,
