  QV = `Ou glisser-déposer les fichiers ici`,
  $V = `Visibilité`,
  eH = `<1>Publique</1>\xA0: les icônes seront visibles publiquement une fois publiées.`,
  tH = `<1>Masquée</1>\xA0: la visibilité des icônes peut être limitée à quelques branches spécifiques du build à des fins de test.`,
