  xH = `Erreur\xA0: l'icône\xA0PNG doit être un carré d'au moins %1$s\xA0px par %1$s\xA0px.`,
  SH = `%1$s\xA0icône en attente`,
  CH = `%1$s\xA0icônes en attente`,
  wH = `Les repères temporels, nouveaux ou mis à jour, doivent être publiés avec vos autres paramètres Steamworks.`,
  TH = `Publier`,
  EH = `Icônes publiques`,
  DH = `Vous pouvez y accéder depuis toutes les branches, dont celle par défaut via les appels d'API.`,
  OH = `En tant qu'icônes publiques, elles peuvent être référencées n'importe où et elles ne peuvent pas être supprimées ou renommées. Vous pouvez mettre à jour l'image si nécessaire.`,
  kH = `Configurez la visibilité de vos nouvelles icônes sur «\xA0Publique\xA0» si vous souhaitez les rendre visibles de tout le monde.`,
  AH = `Icônes masquées`,
  jH = `Configurez la visibilité de vos nouvelles icônes sur «\xA0Masquée\xA0» pour les essayer dans un premier temps avant de les rendre visibles. Utilisez les ensembles ci-dessous pour associer des icônes spécifiques à certaines branches de builds si vous devez en restreindre l'accès.`,
  MH = `Utilisez des icônes masquées pour effectuer un test avant publication.`,
  NH = `non attribué`,
  PH = `Ces icônes n'apparaitront dans aucun build`,
  FH = `Rendre tous les repères masqués publics`,
  IH = `Télécharger pour le test en local`,
  LH = `Assemble un seul fichier\xA0SVG que Steam peut utiliser pour le rendu des icônes. Ce fichier contiendra toutes les icônes publiques ainsi que celles dans l'ensemble masqué.`,
  RH = `Crée des icônes masquées à des fins de test avant de les publier.`,
  zH = `Restriction aux branches\xA0:`,
  BH = `Aucune branche sélectionnée`,
  VH = `Créer un ensemble de branches`,
  HH = `Les ensembles de branches vous aident à organiser vos tests d'icônes masquées en limitant l'accès des icônes à des builds de branches spécifiques.`,
  UH = `Ensemble de branches sans nom %1$s`,
  WH = `Restriction de branche`,
  GH = `Limite la visibilité de certaines icônes à certaines branches uniquement.`,
  KH = `Ensemble de branches %1$s`,
  qH = `Modifier la sélection de branches`,
  JH = `Publier la branche`,
  YH = `Dupliquer le repère temporel`,
  XH = `Choisissez un repère publié de la liste ci-dessous à dupliquer dans l'ensemble de branches %1$s. Les repères déjà présents dans cet ensemble ne sont pas concernés.`,
  ZH = `Repère temporel dupliqué avec succès. `,
  QH = `Facultatif\xA0: sélectionne une ou plusieurs branches auxquelles associer ces ressources. Toute personne qui exécute les branches sélectionnées pourra voir les ressources. Si une branche non protégée par un mot de passe est sélectionnée, alors les icônes seront considérées comme publiquement visibles.`,
  $H = `Aucun changement n'a été effectué à la liste des branches.`,
  eU = `Des modifications ont été apportées à la liste des branches. %1$s\xA0noms de branches ont été ajoutés. %2$s\xA0noms de branches ont été supprimés.`,
  tU = `Cette branche est protégée par un mot de passe.`,
  nU = `Créer un ensemble de branches`,
  rU = `Modifier l'ensemble de branches`,
  iU = `Nom de l'ensemble de branches (interne uniquement)`,
  aU = `Description de l'ensemble de branches (interne uniquement, facultatif)`,
