  cU = `Publication`,
  lU = `Les icônes suivantes seront publiées\xA0:`,
  uU = `%2$s a %1$s\xA0icône à publier.`,
  dU = `%2$s a %1$s\xA0icônes à publier.`,
  fU = `✔ Publication de %1$s réalisée avec succès\xA0!`,
  pU = `Faites glisser une icône masquée ici pour restreindre son accès à certaines branches seulement.`,
  mU = `Faites glisser une icône ici pour la rendre visible auprès de toute la clientèle.`,
  hU = `Faites glisser ces icônes vers un ensemble de branches ci-dessous pour en contrôler la visibilité branche par branche.`,
  gU = `Faites glisser ces icônes dans la zone ci-dessus pour les rendre visibles de tout le monde.`,
  _U = `publication en attente`,
  vU = `Fichiers de repères publiés`,
  yU = `Les ensembles de branches et les icônes publiques ci-dessus peuvent fournir des repères de timeline aux branches suivantes. Si un ensemble de branches ne comporte aucune icône publiée, alors ses branches ne pourront pas contribuer\xA0:`,
  bU = `Ces ensembles de branches ne disposent pas de leurs propres fichiers publiés. La clientèle qui aura sélectionné ces branches devra utiliser les repères de la timeline par défaut.`,
