  jU = `Créez et mettez à jour les succès pour votre jeu.`,
  MU = `Pour de meilleurs résultats, nous recommandons d'utiliser des images\xA0PNG de 256\xA0×\xA0256\xA0pixels pour les icônes de succès. La taille minimale acceptée est de 64\xA0×\xA064, mais il vaut mieux utiliser la taille la plus grande. Nous vous conseillons d'utiliser des images colorées pour les succès obtenus, et en niveaux de gris pour les succès non obtenus.`,
  NU = `Comme les succès peuvent apparaitre à divers endroits de la communauté\xA0Steam, les icônes et noms choisis doivent convenir à tout public et à tout âge. Valve se réserve le droit de retirer un produit de la vente si ses succès ne respectent pas les <1>règles du contenu communautaire</1> ou sont considérés comme offensants.`,
  PU = `Pour finir d'activer les succès, et arriver au bout de la liste de vérification pour la sortie, vous devez également cocher la case correspondante dans la section <1>«\xA0Fonctionnalités prises en charge\xA0»</1>.`,
